const fs = require('fs');

const data = fs.readFileSync(0, 'utf8');
let idx = 0;

function nextInt() {
  while (idx < data.length && data.charCodeAt(idx) <= 32) idx++;
  let num = 0;
  while (idx < data.length && data.charCodeAt(idx) > 32) {
    num = num * 10 + (data.charCodeAt(idx) - 48);
    idx++;
  }
  return num;
}

const N = nextInt();
const K = nextInt();
const U = nextInt();

const occ = Array.from({ length: U + 1 }, () => []);

for (let i = 1; i <= N; i++) {
  for (let j = 0; j < K; j++) {
    const x = nextInt();
    occ[x].push(i);
  }
}

const remaining = new Int32Array(N + 1);
remaining.fill(K);

let minTime = Infinity;
let winners = [];

for (let t = 1; t <= U; t++) {
  const x = nextInt();
  const list = occ[x];

  for (let p = 0; p < list.length; p++) {
    const card = list[p];
    const rem = --remaining[card];

    if (rem === 0) {
      if (t < minTime) {
        minTime = t;
        winners = [card];
      } else if (t === minTime) {
        winners.push(card);
      }
    }
  }
}

winners.sort((a, b) => a - b);
console.log(winners.join(' '));
